      :root {
        --blue: #448aff;
        --blue-dark: #448aff;
        --text: #433d4b;
        --label: #000000;
        --placeholder: #c4c4c4;
        --panel: #f9fcff;
      }

      * {
        box-sizing: border-box;
        margin: 0;
        padding: 0;
      }

      html,
      body {
        min-height: 100%;
      }

      body {
        font-family: "Poppins", sans-serif;
        background: #ffffff;
        color: var(--text);
      }

      /* Sign In Design - forgot/update password (Figma 1920×1080) */
      .page {
        position: relative;
        width: 100%;
        min-height: 100vh;
        background: #ffffff;
        overflow: hidden;
        display: grid;
        grid-template-columns: 1fr minmax(280px, 38.177%);
      }

      .signin-bg {
        position: absolute;
        inset: 0;
        overflow: hidden;
        pointer-events: none;
        z-index: 0;
      }

      .signin-bg-design {
        position: absolute;
        width: 114.85%; /* 2205.12 / 1920 */
        height: 117.504%; /* 1269.04 / 1080 */
        left: 0;
        top: -8.0556%; /* -87 / 1080 */
      }

      /* Ellipse 1428 — warm yellow on the right */
      .ellipse-1428 {
        position: absolute;
        width: 55.253%; /* 1218.4 / 2205.12 */
        height: 57.582%; /* 730.74 / 1269.04 */
        left: 62.872%; /* 1386.4 / 2205.12 */
        top: 0;
        background: #fff7eb;
        opacity: 0.46;
        filter: blur(50px);
        border-radius: 50%;
        transform: rotate(85.77deg);
        transform-origin: center;
      }

      .signin-bg-overlay {
        position: absolute;
        inset: 0;
        background: rgba(255, 255, 255, 0.1);
      }

      .panel,
      .intro {
        position: relative;
        z-index: 1;
      }

      /* Left form panel */
      .panel {
        background: #f9fcff;
        border-right: 0.5px solid #448aff;
        min-height: 100vh;
        padding: 4.5vh 4vw 4vh;
        display: flex;
        flex-direction: column;
      }

      .panel h2 {
        font-family: "Poppins", sans-serif;
        font-weight: 600;
        font-size: clamp(18px, 1.25vw, 24px);
        line-height: 1.4;
        letter-spacing: 0.02em;
        color: #448AFF;
        margin-bottom: 0.4vh;
      }

      .panel-hint {
        font-family: "Poppins", sans-serif;
        font-style: italic;
        font-weight: 500;
        font-size: clamp(13px, 0.9vw, 16px);
        line-height: 1.4;
        letter-spacing: 0.02em;
        color: #448AFF;
        margin-bottom: 3vh;
      }

      .form {
        display: flex;
        flex-direction: column;
        gap: 1.6vh;
        flex: 1;
      }

      .field {
        display: flex;
        flex-direction: column;
        gap: 0.4vh;
      }

      .field label {
        font-family: "Poppins", sans-serif;
        font-weight: 500;
        font-size: clamp(13px, 0.9vw, 16px);
        line-height: 1.4;
        letter-spacing: 0.02em;
        color: #000000;
      }

      .field input {
        width: 100%;
        max-width: 720px;
        height: 42px;
        background: #ffffff;
        border: 1px solid #448aff;
        border-radius: 8px;
        padding: 0 16px;
        font-family: "Poppins", sans-serif;
        font-weight: 400;
        font-size: clamp(13px, 0.9vw, 15px);
        letter-spacing: 0.02em;
        color: #000000;
        outline: none;
      }

      .field input::placeholder {
        color: #c4c4c4;
      }

      .field input:focus {
        box-shadow: 0 0 0 3px rgba(68, 138, 255, 0.15);
      }

      .actions {
        margin-top: auto;
        display: flex;
        justify-content: flex-end;
        padding-top: 2vh;
      }

      .continue-btn {
        width: 200px;
        max-width: 100%;
        height: 38px;
        border: none;
        background: #448aff;
        box-shadow: 2px 2px 4px rgba(0, 0, 0, 0.25);
        border-radius: 10px;
        font-family: "Poppins", sans-serif;
        font-weight: 500;
        font-size: 14px;
        color: #ffffff;
        letter-spacing: 0.02em;
        cursor: pointer;
      }

      .continue-btn:hover {
        background: #3478ef;
      }

      /* Right copy */
      .intro {
        display: flex;
        flex-direction: column;
        justify-content: space-between;
        align-items: flex-end;
        padding: 7vh 4vw 6vh;
        min-height: 100vh;
        text-align: right;
      }

      .intro h1 {
        max-width: 420px;
        font-family: "Montserrat", sans-serif;
        font-weight: 700;
        font-size: clamp(26px, 2.2vw, 38px);
        line-height: 1.25;
        letter-spacing: 0.02em;
        color: #448aff;
        text-shadow: 3px 3px 10px rgba(68, 138, 255, 0.25);
        text-align: right;
      }

      .intro-footer {
        display: flex;
        flex-direction: row;
        flex-wrap: nowrap;
        align-items: baseline;
        justify-content: flex-end;
        gap: 0.35em;
        white-space: nowrap;
      }

      .intro-footer p {
        font-family: "Montserrat", sans-serif;
        font-weight: 400;
        font-size: clamp(14px, 1.05vw, 18px);
        line-height: 1.3;
        letter-spacing: 0.02em;
        color: #433d4b;
        margin: 0;
        white-space: nowrap;
      }

      .intro-footer a {
        font-family: "Montserrat", sans-serif;
        font-weight: 700;
        font-size: clamp(14px, 1.05vw, 18px);
        line-height: 1.3;
        letter-spacing: 0.02em;
        text-decoration-line: underline;
        color: #448AFF;
        white-space: nowrap;
      }

      @media (max-width: 980px) {
        .page {
          grid-template-columns: 1fr;
        }

        .panel {
          border-right: none;
          border-bottom: 0.5px solid #448aff;
          min-height: auto;
          order: 2;
          padding: 24px 20px 32px;
        }

        .intro {
          min-height: auto;
          order: 1;
          align-items: center;
          text-align: center;
          padding: 28px 20px 18px;
        }

        .intro h1 {
          text-align: center;
        }

        .intro-footer {
          justify-content: center;
        }

        .actions {
          justify-content: stretch;
        }

        .continue-btn {
          width: 100%;
        }
      }
